/**
 * Build 3.1 end-to-end integration test.
 *
 * Proves the whole local pipeline works:
 *
 *   goal -> Scout report -> journey.json -> execution.json
 *
 * This uses the **real** planner and the **real** executor. The journey plan is
 * generated by Build 2 from a goal and a Scout report; it is never hand-authored
 * here. Everything runs against a local fixture server on an ephemeral port, so
 * no external website, network dependency, or AI provider is involved.
 *
 * The plan is read as bytes before and after execution and compared, so plan
 * immutability is asserted rather than assumed.
 */

import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import type { Server } from 'node:http';
import { mkdtemp, readFile, rm, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join, resolve } from 'node:path';
import { dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { chromium } from 'playwright';

import { runScout } from '../../src/scout/scout.js';
import { planJourney } from '../../src/journey/plan.js';
import { executeJourney } from '../../src/executor/executor.js';
import { startFixtureServer, stopFixtureServer } from '../fixtures/server.js';
import type { ExecutionReport } from '../../src/executor/types.js';
import type { JourneyPlan } from '../../src/journey/types.js';

const HERE = dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = resolve(HERE, '..', '..');

let server: Server;
let origin: string;
let available = false;
let workDir: string;

/** The goal this pipeline is built around. */
const GOAL = 'Try to open the ticket purchase flow';

beforeAll(async () => {
  try {
    await chromium.launch({ headless: true });
    available = true;
  } catch {
    available = false;
  }
  const started = await startFixtureServer();
  server = started.server;
  origin = started.origin;
  workDir = await mkdtemp(join(tmpdir(), 'crashlab-pipeline-'));
}, 60_000);

afterAll(async () => {
  if (server) await stopFixtureServer(server);
  if (workDir) await rm(workDir, { recursive: true, force: true });
});

describe('goal -> scout -> journey -> execution', () => {
  it('runs the whole pipeline with no external dependency', async () => {
    if (!available) return;

    // --- Build 1: scout the local fixture --------------------------------
    const scout = await runScout({
      url: `${origin}/shop`,
      headless: true,
      settleMs: 100,
      timeoutMs: 15_000,
    });

    // The page really is a shop, with a visible Buy control to act on.
    const buy = scout.interactiveElements.find((element) => element.id === 'buy');
    expect(buy, 'the fixture should expose a Buy button').toBeDefined();
    expect(buy?.visible).toBe(true);
    expect(buy?.enabled).toBe(true);

    // --- Build 2: plan from the goal and the Scout report ----------------
    const plan: JourneyPlan = planJourney(GOAL, scout, 'reports/scout.json');

    // The plan must contain at least one real, executable-shaped action. This
    // is the specific gap Build 3.1 closed: Build 2 previously emitted only
    // identify and assert.
    const actionable = plan.steps.filter((step) => step.action !== 'identify' && step.action !== 'assert');
    expect(actionable.length, 'the generated plan should contain a real action').toBeGreaterThan(0);
    expect(actionable.some((step) => step.action === 'click')).toBe(true);

    // Every step still honours the Build 2 contract.
    expect(plan.schemaVersion).toBe('1.0');
    expect(plan.steps.every((step) => step.executable === false)).toBe(true);
    expect(plan.goal).toBe(GOAL);
    expect(plan.normalizedGoal).toBe(GOAL.toLowerCase());

    // The generated plan carries no invented data of any kind.
    const planJson = JSON.stringify(plan);
    expect(planJson).not.toMatch(/\b4\d{15}\b/);
    expect(planJson).not.toMatch(/password["']?\s*[:=]\s*["'][^"']+/i);

    // --- write the plan, and capture its bytes ---------------------------
    const journeyPath = join(workDir, 'journey.json');
    const journeyContents = `${JSON.stringify(plan, null, 2)}\n`;
    await writeFile(journeyPath, journeyContents, 'utf8');
    const bytesBefore = await readFile(journeyPath);

    // --- Build 3: execute the generated plan ------------------------------
    const report: ExecutionReport = await executeJourney({
      plan,
      planPath: 'reports/journey.json',
      screenshots: true,
      evidenceDir: join(workDir, 'evidence'),
    });

    // --- the plan must be byte-identical after execution ------------------
    const bytesAfter = await readFile(journeyPath);
    expect(bytesAfter.equals(bytesBefore), 'journey.json must be byte-identical after execution').toBe(true);
    expect(bytesAfter.toString('utf8')).toBe(journeyContents);

    // --- execution.json is produced --------------------------------------
    const executionPath = join(workDir, 'execution.json');
    await writeFile(executionPath, `${JSON.stringify(report, null, 2)}\n`, 'utf8');
    const written = JSON.parse(await readFile(executionPath, 'utf8')) as ExecutionReport;

    expect(written.schemaVersion).toBe('1.0');
    expect(written.journeyPlanSchemaVersion).toBe('1.0');
    expect(written.goal).toBe(GOAL);

    // --- per-step results, in order ---------------------------------------
    expect(written.steps.length).toBe(plan.steps.length);
    expect(written.steps.map((step) => step.id)).toEqual(plan.steps.map((step) => step.id));
    expect(written.steps.map((step) => step.order)).toEqual(plan.steps.map((step) => step.order));
    for (const step of written.steps) {
      expect(['passed', 'failed', 'blocked', 'skipped']).toContain(step.status);
      expect(step.durationMs).toBeGreaterThanOrEqual(0);
    }

    // --- the executor actually performed a click -------------------------
    const clicks = written.steps.filter((step) => step.action === 'click');
    expect(clicks.length).toBeGreaterThan(0);
    const performed = clicks.find((step) => step.status === 'passed');
    expect(performed, 'at least one generated click should have executed').toBeDefined();
    expect(performed!.selectedLocator).toBeTruthy();

    // The click really changed the page, which is what makes this a pipeline
    // test rather than a smoke test.
    const observed = written.steps.filter((step) => step.observations?.exists);
    expect(observed.length).toBeGreaterThan(0);

    // --- no bug vocabulary anywhere ---------------------------------------
    expect(JSON.stringify(written)).not.toMatch(/bugConfirmed|confirmed.?bug|anomalyConfirmed|severity|reproductionRate/i);
    expect(written.executor.retries).toBe(0);
    expect(written.executor.safeTestMode).toBe(true);
  }, 90_000);

  it('is deterministic: the same goal and Scout report produce the same plan', async () => {
    if (!available) return;
    const scout = await runScout({ url: `${origin}/shop`, headless: true, settleMs: 100, timeoutMs: 15_000 });
    const first = JSON.stringify(planJourney(GOAL, scout, 'reports/scout.json'), null, 2);
    for (let i = 0; i < 3; i++) {
      expect(JSON.stringify(planJourney(GOAL, scout, 'reports/scout.json'), null, 2)).toBe(first);
    }
  }, 60_000);

  it('never plans an action against a hidden, disabled or generic control', async () => {
    if (!available) return;
    const scout = await runScout({ url: `${origin}/shop`, headless: true, settleMs: 100, timeoutMs: 15_000 });
    const plan = planJourney(GOAL, scout, 'reports/scout.json');

    // The hidden, disabled and duplicate Buy controls must never be an action.
    const elements = new Map(scout.interactiveElements.map((element) => [element.id, element]));
    for (const step of plan.steps) {
      if (step.action === 'identify' || step.action === 'assert') continue;
      for (const elementId of step.targetElementIds) {
        const element = elements.get(elementId);
        if (!element) continue;
        expect(
          element.visible,
          `step ${step.id} targets a hidden control (${elementId})`,
        ).toBe(true);
        expect(
          element.enabled,
          `step ${step.id} targets a disabled control (${elementId})`,
        ).toBe(true);
      }
    }
  }, 60_000);

  it('explains why a weak or ambiguous match stayed observational', async () => {
    if (!available) return;
    const scout = await runScout({ url: `${origin}/shop`, headless: true, settleMs: 100, timeoutMs: 15_000 });
    const plan = planJourney(GOAL, scout, 'reports/scout.json');

    // The two identical "Buy" buttons make the generic buy role ambiguous, so
    // the planner must say so rather than silently picking one.
    const warnings = plan.warnings.join(' ');
    expect(warnings).toMatch(/observational|ambiguous|equal/i);
  }, 60_000);
});

describe('generated login plan: fill steps carry no credentials', () => {
  it('produces fill steps that execution blocks without test data', async () => {
    if (!available) return;

    const scout = await runScout({
      url: `file:///${join(REPO_ROOT, 'tests', 'fixtures', 'login.html').replace(/\\/g, '/')}`,
      headless: true,
      settleMs: 100,
      timeoutMs: 15_000,
    });

    const plan = planJourney('Try to log in', scout, 'reports/scout.json');
    const fills = plan.steps.filter((step) => step.action === 'fill');

    // A generated login plan should now contain real fill steps.
    expect(fills.length).toBeGreaterThan(0);

    // They must carry target information only. The journey step schema has no
    // value field at all, so the check is that no data-bearing field exists.
    for (const fill of fills) {
      expect(fill.targetElementIds.length + fill.locatorCandidates.length).toBeGreaterThan(0);
      expect(Object.keys(fill)).not.toContain('value');
      expect(Object.keys(fill)).not.toContain('text');
      expect(Object.keys(fill)).not.toContain('data');
    }

    // The plan as a whole invents no credential.
    expect(JSON.stringify(plan)).not.toMatch(/hunter2|SafeFixturePassword|letmein/i);

    // Executing without test data must block, not guess.
    const report = await executeJourney({
      plan,
      planPath: 'reports/journey.json',
      screenshots: false,
    });
    const blocked = report.steps.filter((step) => step.status === 'blocked' && step.error?.reason === 'missing-test-data');
    expect(blocked.length, 'fill steps must block without explicit test data').toBeGreaterThan(0);
  }, 90_000);
});

describe('screenshot omission after sensitive data', () => {
  it('omits screenshots once test data has entered the page', async () => {
    if (!available) return;

    const { validateJourneyPlan } = await import('../../src/executor/planValidator.js');
    const { planWith, step } = await import('../fixtures/journeyPlans.js');

    const plan = validateJourneyPlan(
      JSON.parse(
        JSON.stringify(
          planWith(
            [
              step({ id: 'step-001', order: 1, intent: 'identify_password_field', action: 'fill', locatorCandidates: ["page.getByTestId('password')"] }),
              step({ id: 'step-002', order: 2, action: 'submit', locatorCandidates: ["page.getByTestId('submit-signup')"] }),
            ],
            { goal: 'sensitive run', target: { url: `${origin}/executor`, finalUrl: null, title: 'x' } },
          ),
        ),
      ),
      'test.json',
    );

    const report = await executeJourney({
      plan,
      planPath: 'reports/journey.json',
      testData: { password: 'SafeFixturePassword123!' },
      screenshots: true,
      evidenceDir: join(workDir, 'evidence-sensitive'),
    });

    // The initial screenshot is taken before anything is typed.
    expect(report.rawEvidence.screenshots).toContain('initial.png');

    // The screenshot of the very step that typed the password is omitted too:
    // the value is already in the DOM when the step returns.
    expect(report.rawEvidence.screenshots).not.toContain('step-001-after.png');
    expect(report.rawEvidence.screenshots).not.toContain('step-002-after.png');
    expect(report.rawEvidence.screenshots).not.toContain('final.png');
    expect(report.redaction.screenshotsOmittedAfterSensitiveData).toBe(true);

    // The omission is explained per step, not just implied by an absent file.
    const fillStep = report.steps.find((s) => s.id === 'step-001');
    expect(fillStep?.evidence.screenshot).toBeNull();
    expect(fillStep?.evidence.screenshotOmitted).toBe(true);
    expect(fillStep?.evidence.screenshotOmittedReason).toBe('sensitive-data-entered');

    // The raw value appears nowhere in the report.
    expect(JSON.stringify(report)).not.toContain('SafeFixturePassword123!');
  }, 90_000);

  it('does not screenshot a page that echoes a password, even for failures', async () => {
    if (!available) return;

    const { validateJourneyPlan } = await import('../../src/executor/planValidator.js');
    const { planWith, step } = await import('../fixtures/journeyPlans.js');

    // The fixture writes the submitted password into #submit-result, so a
    // screenshot after submission would contain it.
    const plan = validateJourneyPlan(
      JSON.parse(
        JSON.stringify(
          planWith(
            [
              step({ id: 'step-001', order: 1, intent: 'identify_password_field', action: 'fill', locatorCandidates: ["page.getByTestId('password')"] }),
              // A missing target, so this step fails and would want a failure
              // screenshot - which must still be omitted.
              step({ id: 'step-002', order: 2, action: 'click', locatorCandidates: ["page.getByTestId('nope')"] }),
            ],
            { goal: 'echo run', target: { url: `${origin}/executor`, finalUrl: null, title: 'x' } },
          ),
        ),
      ),
      'test.json',
    );

    const report = await executeJourney({
      plan,
      planPath: 'reports/journey.json',
      testData: { password: 'SafeFixturePassword123!' },
      continueOnFailure: true,
      screenshots: true,
      evidenceDir: join(workDir, 'evidence-echo'),
    });

    // The failure screenshot is omitted for the same reason as a success one.
    expect(report.rawEvidence.screenshots).not.toContain('step-002-failure.png');
    expect(report.rawEvidence.screenshots).not.toContain('final.png');
    expect(JSON.stringify(report)).not.toContain('SafeFixturePassword123!');
  }, 90_000);
});
